<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageTargetVO;

trait MessageTargetAttributeHolder
{
    protected MessageTargetVO|string|null $target = null;
    protected bool $targetAssigned = false;

    public function getTargetOrDefault(MessageTargetVO $target): MessageTargetVO
    {
        if ($this->targetAssigned) {
            \assert(null !== $this->target);
            return MessageTargetVO::from($this->target);
        } else {
            return $target;
        }
    }
    public function target(MessageTargetVO|string $target): static
    {
        $this->target = $target;
        $this->targetAssigned = true;
        return $this;
    }
    public function getTarget(): ?string
    {
        return $this->target instanceof MessageTargetVO ? $this->target->value() : $this->target;
    }
    public function isTargetAssigned(): bool
    {
        return $this->targetAssigned;
    }
    public function writeTargetTo(mixed $att): void
    {
        if ($this->targetAssigned) {
            \assert(null !== $this->target);
            $att->target($this->target);
        }
    }
    public function readTargetFrom(mixed $att): void
    {
        if ($att->isTargetAssigned()) {
            $target = $att->getTarget();
            \assert(null !== $target);
            $this->target($target);
        }
    }
    public function unsetTarget(): static
    {
        $this->targetAssigned = false;
        return $this;
    }
    protected function withDefaultTarget(): void
    {
    }
    protected function withAssertedTargetRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->targetAssigned = $this->targetAssigned) {
            $value->target = MessageTargetVO::tryFrom($this->target, $errorsList);
        }
    }
}
